insert into public.categories (id, title, sort_order) values
  ('salah', 'Daily prayers', 0),
  ('sunnah-prayers', 'Sunnah & nafl prayers', 1),
  ('quran', 'Qurʾān', 2),
  ('dhikr', 'Dhikr & remembrance', 3),
  ('fasting', 'Fasting', 4),
  ('character', 'Character & charity', 5),
  ('growth', 'Study & growth', 6),
  ('wellbeing', 'Health & wellbeing', 7)
insert into public.presets (id, category_id, name, detail, evidence, default_schedule, hijri_schedule, target_count, target_unit, essential, sort_order) values
  ('fajr-on-time', 'salah', 'Prayed Fajr on time', 'Pray the two obligatory rakʿahs of Fajr in its window — from true dawn (ṣubḥ ṣādiq) until just before sunrise.', 'The best deed is prayer at its appointed time (Bukhari 527, Muslim 85).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 0),
  ('dhuhr-on-time', 'salah', 'Prayed Dhuhr on time', 'Pray the four obligatory rakʿahs of Dhuhr in its window — from just after the sun passes its zenith (zawāl) until ʿAṣr begins.', 'The best deed is prayer at its appointed time (Bukhari 527, Muslim 85).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 1),
  ('asr-on-time', 'salah', 'Prayed ʿAṣr on time', 'Pray the four obligatory rakʿahs of ʿAṣr in its window — from when a shadow grows to equal the object casting it until sunset, ideally before the sun yellows.', 'Whoever misses ʿAṣr, it is as if he lost his family and wealth (Bukhari 552).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 2),
  ('maghrib-on-time', 'salah', 'Prayed Maghrib on time', 'Pray the three obligatory rakʿahs of Maghrib in its window — from just after sunset until the red twilight fades.', 'The best deed is prayer at its appointed time (Bukhari 527, Muslim 85).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 3),
  ('isha-on-time', 'salah', 'Prayed ʿIshāʾ on time', 'Pray the four obligatory rakʿahs of ʿIshāʾ in its window — from when the twilight fades until Islamic midnight, and no later than true dawn.', 'The most burdensome prayers on the hypocrites are ʿIshāʾ and Fajr (Bukhari 657, Muslim 651).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 4),
  ('prayer-in-congregation', 'salah', 'Prayed in congregation', 'Pray each of the five daily prayers in congregation (jamāʿah) — with at least one other person, at the masjid wherever you can. Count each prayer you make in jamāʿah.', 'Prayer in congregation is twenty-seven times superior to prayer alone (Bukhari 645, Muslim 650).', '{0,1,2,3,4,5,6}'::integer[], null, 5, 'prayers', false, 5),
  ('sunnah-before-fajr', 'sunnah-prayers', 'Prayed two rakʿah before Fajr', 'Pray the two Sunnah rakʿahs before the obligatory Fajr prayer.', 'The two rakʿahs before Fajr are better than the world and all it contains (Muslim 725).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 6),
  ('rawatib-12', 'sunnah-prayers', 'Prayed the 12 rawātib rakʿah', 'Pray the twelve confirmed Sunnah rakʿahs across the day: 2 before Fajr, 4 before & 2 after Dhuhr, 2 after Maghrib, 2 after ʿIshāʾ. Prefer the per-prayer habits below if you’d rather track each one on its own.', 'Whoever prays twelve rakʿahs in a day and night, a house is built for him in Paradise (Muslim 728).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 7),
  ('sunnah-before-dhuhr', 'sunnah-prayers', 'Prayed four rakʿah before Dhuhr', 'Pray the four confirmed Sunnah rakʿah before the obligatory Dhuhr prayer.', 'Among the twelve confirmed rawātib — four before Dhuhr (Muslim 728; Tirmidhi 415, ṣaḥīḥ); the Prophet ﷺ would never leave them (Bukhari 1182).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 8),
  ('sunnah-after-dhuhr', 'sunnah-prayers', 'Prayed two rakʿah after Dhuhr', 'Pray the two confirmed Sunnah rakʿah after the obligatory Dhuhr prayer.', 'Among the twelve confirmed rawātib — two after Dhuhr (Muslim 728; Tirmidhi 415, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 9),
  ('sunnah-before-asr', 'sunnah-prayers', 'Prayed four rakʿah before ʿAṣr', 'Pray four rakʿah before the obligatory ʿAṣr prayer — a recommended (not confirmed) Sunnah, prayed as two pairs.', 'May Allāh have mercy on a man who prays four rakʿah before ʿAṣr (Abu Dawud 1271; Tirmidhi 430, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 10),
  ('sunnah-after-maghrib', 'sunnah-prayers', 'Prayed two rakʿah after Maghrib', 'Pray the two confirmed Sunnah rakʿah after the obligatory Maghrib prayer, at home where you can.', 'Among the twelve confirmed rawātib — two after Maghrib (Muslim 728; Tirmidhi 415, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 11),
  ('sunnah-after-isha', 'sunnah-prayers', 'Prayed two rakʿah after ʿIshāʾ', 'Pray the two confirmed Sunnah rakʿah after the obligatory ʿIshāʾ prayer, before your Witr.', 'Among the twelve confirmed rawātib — two after ʿIshāʾ (Muslim 728; Tirmidhi 415, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 12),
  ('witr', 'sunnah-prayers', 'Prayed Witr before sleeping', 'Pray an odd number of rakʿahs (at least one) as Witr after ʿIshāʾ, making it the last prayer of your night.', 'Make Witr the last of your night prayer (Bukhari 998, Muslim 751).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 13),
  ('duha', 'sunnah-prayers', 'Prayed Duhā (2 rakʿah)', 'Pray at least two rakʿahs of Duhā in the morning — from about 15–20 minutes after sunrise until just before Dhuhr (zawāl).', 'Two rakʿahs of Duhā suffice as the charity due upon every joint each morning (Muslim 720).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 14),
  ('tahajjud', 'sunnah-prayers', 'Prayed Tahajjud', 'Pray at least two rakʿahs of night prayer (Qiyām al-Layl) after waking in the last part of the night.', 'The best prayer after the obligatory is the night prayer (Muslim 1163).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 15),
  ('two-rakah-after-wudu', 'sunnah-prayers', 'Prayed two rakʿah after wuḍūʾ', 'After wuḍūʾ, pray two rakʿah with full presence, before your mind wanders.', 'Bilāl prayed two rakʿah after every wuḍūʾ; the Prophet ﷺ heard his footsteps in Paradise (Bukhari 1149, Muslim 2458).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 16),
  ('tahiyyat-al-masjid', 'sunnah-prayers', 'Prayed two rakʿah on entering the masjid', 'Whenever you enter a masjid, pray two rakʿah (taḥiyyat al-masjid) before sitting down. On a day you don’t go, skip it.', 'When one of you enters the masjid, let him pray two rakʿah before sitting (Bukhari 444, Muslim 714).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 17),
  ('two-rakah-before-maghrib', 'sunnah-prayers', 'Prayed two rakʿah before Maghrib', 'Between the Maghrib adhān and iqāmah, pray two light rakʿah.', '"Pray before Maghrib" — for whoever wishes; between every adhān and iqāmah is a prayer (Bukhari 1183, 627).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 18),
  ('quran-daily-page', 'quran', 'Read 1 page of Qurʾān', 'Read at least one page of the Qurʾān today — set a larger portion if you wish.', 'Read the Qurʾān, for it will intercede for its companions on the Day of Resurrection (Muslim 804).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 19),
  ('quran-daily-juz', 'quran', 'Read 1 juzʾ of Qurʾān', 'Read one full juzʾ (1/30th of the Qurʾān) today — this pace completes the whole Qurʾān every month.', 'The Prophet ﷺ told ʿAbdullāh ibn ʿAmr to complete a recitation of the Qurʾān every month (Bukhari 5054, Muslim 1159).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 20),
  ('quran-sabaq', 'quran', 'Memorized new Qurʾān', 'Memorize a new portion of Qurʾān today — a few lines or a page — building on what you already know.', 'It will be said to the companion of the Qurʾān: recite and ascend, reciting as you used to in the world — your rank is at the last verse you recite (Abu Dawud 1464, Tirmidhi 2914, ḥasan ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 21),
  ('quran-murajaah', 'quran', 'Revised memorized Qurʾān', 'Revise a portion you’ve already memorized — a few lines or a page — so it stays fresh rather than fading. Set a larger portion if you wish.', 'The one who memorizes the Qurʾān is like the owner of tied camels — hold on and you keep them, let go and they run off (Bukhari 5031, Muslim 789).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 22),
  ('surah-al-mulk', 'quran', 'Recited al-Mulk at night', 'Recite Sūrat al-Mulk (chapter 67) before sleeping.', 'A sūrah of thirty verses interceded for its companion until he was forgiven — al-Mulk (Tirmidhi 2891, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 23),
  ('surah-al-kahf-friday', 'quran', 'Recited al-Kahf on Friday', 'Recite Sūrat al-Kahf (chapter 18) on Friday — any time from Maghrib Thursday to Maghrib Friday.', 'Whoever reads Sūrat al-Kahf on Friday has light between the two Fridays (al-Ḥākim/al-Bayhaqī, ṣaḥīḥ).', '{5}'::integer[], null, null, null, false, 24),
  ('baqarah-last-verses', 'quran', 'Recited the last two verses of al-Baqarah', 'Recite the final two verses of Sūrat al-Baqarah (2:285–286) at night.', 'Whoever recites the last two verses of al-Baqarah at night, they suffice him (Bukhari 5009, Muslim 807).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 25),
  ('three-quls-sleep', 'quran', 'Recited the three Quls before sleep', 'Before sleeping, recite al-Ikhlāṣ, al-Falaq, and an-Nās — cup your hands, recite into them, and wipe over yourself three times.', 'Each night the Prophet ﷺ recited the Muʿawwidhāt into his hands and wiped over his body (Bukhari 5017).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 26),
  ('surah-al-kafirun-sleep', 'quran', 'Recited al-Kāfirūn before sleeping', 'Recite Sūrat al-Kāfirūn (chapter 109) before sleeping.', 'The Prophet ﷺ taught it as a disavowal of shirk before sleeping (Abu Dawud 5055, Tirmidhi 3403, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 27),
  ('al-imran-last-ten', 'quran', 'Recited the last ten āyāt of Āl ʿImrān', 'On rising in the night, recite the closing passage of Sūrat Āl ʿImrān — from “Inna fī khalqi s-samāwāti wa-l-arḍ” (verse 190) to the sūrah’s end.', 'On waking the Prophet ﷺ recited the last ten verses of Āl ʿImrān (Bukhari 4569, Muslim 763).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 28),
  ('morning-adhkar', 'dhikr', 'Said the morning adhkār', 'Say the morning remembrances (Adhkār aṣ-Ṣabāḥ) after Fajr, before sunrise.', 'Glorify Him in the morning and the evening (Qurʾān 33:41–42).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 29),
  ('evening-adhkar', 'dhikr', 'Said the evening adhkār', 'Say the evening remembrances (Adhkār al-Masāʾ) between ʿAṣr and Maghrib.', 'Glorify Him in the morning and the evening (Qurʾān 33:41–42).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 30),
  ('tasbih-after-salah', 'dhikr', 'Said tasbīḥ ×33 after each prayer', 'After each obligatory prayer, say SubḥānAllāh, Alḥamdulillāh and Allāhu Akbar 33 times each, then complete the hundred with: lā ilāha illā Allāh waḥdahu lā sharīka lah, lahu-l-mulku wa lahu-l-ḥamd wa huwa ʿalā kulli shayʾin qadīr. Count each of the five prayers you complete it after.', 'Whoever says them after every prayer, his sins are forgiven though they be like the foam of the sea (Muslim 597).', '{0,1,2,3,4,5,6}'::integer[], null, 5, 'prayers', false, 31),
  ('ayat-al-kursi', 'dhikr', 'Recited Āyat al-Kursī after each prayer', 'Recite Āyat al-Kursī (Qurʾān 2:255) after each obligatory prayer. Count each of the five prayers you recite it after.', 'Whoever recites it after every prayer, nothing keeps him from Paradise but death (an-Nasāʾī, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, 5, 'prayers', false, 32),
  ('istighfar-100', 'dhikr', 'Said istighfār ×100', 'Seek Allāh’s forgiveness (astaghfirullāh) at least 100 times through the day.', 'I seek Allāh’s forgiveness and repent to Him a hundred times a day (Muslim 2702).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 33),
  ('tawbah', 'dhikr', 'Made tawbah', 'Turn back to Allāh in sincere repentance for today’s sins — feel remorse, stop the sin, and resolve not to return to it.', 'Every son of Adam sins, and the best of those who sin are those who repent (Tirmidhi 2499, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 34),
  ('salawat', 'dhikr', 'Sent salawāt ×10 on the Prophet ﷺ', 'Send blessings on the Prophet ﷺ at least 10 times today — increase on Fridays.', 'Whoever sends one blessing on me, Allāh sends ten upon him (Muslim 408).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 35),
  ('dua-on-waking', 'dhikr', 'Said the duʿāʾ on waking', 'On opening your eyes, say: Al-ḥamdu lillāhi alladhī aḥyānā baʿda mā amātanā wa ilayhi-n-nushūr.', 'On waking the Prophet ﷺ would say it — "Praise to Allāh who gave us life after death, and to Him is the return" (Bukhari 6312).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 36),
  ('wipe-face-on-waking', 'dhikr', 'Wiped my face on waking', 'On waking, wipe your face with your hand to clear the traces of sleep before rising.', 'On waking, the Prophet ﷺ would sit up and wipe the sleep from his face with his hand (Muslim 763).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 37),
  ('answer-the-adhan', 'dhikr', 'Answered the adhān', 'When you hear the call, repeat the muʾadhdhin’s words, then ask Allāh to grant the Prophet ﷺ al-wasīlah (Allāhumma rabba hādhihi-d-daʿwati-t-tāmmah…).', 'Repeat what the muʾadhdhin says (Bukhari 611); whoever asks al-wasīlah for me after it, my intercession is due for him (Bukhari 614).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, true, 38),
  ('dua-after-wudu', 'dhikr', 'Said the duʿāʾ after wuḍūʾ', 'After wuḍūʾ, say the shahādatayn: Ashhadu an lā ilāha illā Allāh waḥdahu lā sharīka lah, wa ashhadu anna Muḥammadan ʿabduhu wa rasūluh.', 'Whoever says it after wuḍūʾ, the eight gates of Paradise are opened for him (Muslim 234).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 39),
  ('dua-entering-masjid', 'dhikr', 'Said the duʿāʾ entering & leaving the masjid', 'On a day you go to the masjid, enter saying Allāhumma-ftaḥ lī abwāba raḥmatik and leave saying Allāhumma innī asʾaluka min faḍlik. On a day you don’t go, skip it.', 'The Prophet ﷺ taught this on entering and leaving the masjid (Muslim 713).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 40),
  ('kaffarat-al-majlis', 'dhikr', 'Sealed a gathering', 'On any day you sit with others, before you leave say the expiation of the gathering (kaffārat al-majlis): Subḥānaka-llāhumma wa biḥamdik, ashhadu an lā ilāha illā ant, astaghfiruka wa atūbu ilayk. On a day with no gathering, skip it.', 'Whoever says it when leaving a gathering, what occurred in it is forgiven (Tirmidhi 3433, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 41),
  ('restroom-dua', 'dhikr', 'Said the duʿāʾ entering & leaving the restroom', 'Enter saying Allāhumma innī aʿūdhu bika mina-l-khubthi wa-l-khabāʾith; leave saying Ghufrānak.', 'Entering — Bukhari 142, Muslim 375; leaving — Abu Dawud 30, Tirmidhi 7, ṣaḥīḥ.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 42),
  ('fast-mon-thu', 'fasting', 'Kept the Sunnah fast', 'Fast from true dawn (Fajr) to sunset (Maghrib) on Mondays and Thursdays — a voluntary fast the Prophet ﷺ kept regularly.', 'Deeds are presented on Mondays and Thursdays, and I like mine presented while fasting (Tirmidhi 747, ḥasan; Muslim 1162).', '{1,4}'::integer[], null, null, null, false, 43),
  ('fast-white-days', 'fasting', 'Fasted the White Days', 'Fast the three white days — the 13th, 14th, and 15th of each Hijri month — from dawn to sunset.', 'Fasting three days each month is like fasting for life; the Prophet ﷺ enjoined the white days, the 13th, 14th, and 15th (Bukhari 1979; Tirmidhi 761, ṣaḥīḥ).', '{}'::integer[], '{"monthDays":[13,14,15]}'::jsonb, null, null, false, 44),
  ('fast-arafah', 'fasting', 'Fasted the Day of ʿArafah', 'Fast the Day of ʿArafah — the 9th of Dhū al-Ḥijjah — for those not performing Hajj.', 'Fasting the Day of ʿArafah expiates the year before and the year after (Muslim 1162).', '{}'::integer[], '{"dates":[{"month":12,"day":9}]}'::jsonb, null, null, false, 45),
  ('fast-ashura', 'fasting', 'Fasted ʿĀshūrāʾ', 'Fast ʿĀshūrāʾ — the 10th of Muḥarram — together with the 9th (Tāsūʿāʾ), as the Prophet ﷺ resolved to do.', 'Fasting ʿĀshūrāʾ expiates the previous year; "if I live to next year I will fast the ninth" (Muslim 1134).', '{}'::integer[], '{"dates":[{"month":1,"day":9},{"month":1,"day":10}]}'::jsonb, null, null, false, 46),
  ('fast-ramadan', 'fasting', 'Fasted Ramaḍān', 'Fast every day of Ramaḍān from true dawn (Fajr) to sunset (Maghrib) — the obligatory fast of the month.', 'The month of Ramaḍān in which the Qurʾān was revealed … so whoever sights it, let him fast it (Qurʾān 2:185).', '{}'::integer[], '{"months":[9]}'::jsonb, null, null, false, 47),
  ('sadaqah-daily', 'character', 'Gave ṣadaqah (even a smile)', 'Give at least one charity today — money, a helpful act, or a smile to someone you meet.', 'Your smiling at your brother is charity (Tirmidhi 1956, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 48),
  ('good-word', 'character', 'Said a good word', 'Say at least one kind, truthful word to someone today.', 'A good word is charity (Bukhari 2989, Muslim 1009).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 49),
  ('ties-of-kinship', 'character', 'Reached out to family', 'Call, message, or visit at least one family member today — especially one you have drifted from.', 'Whoever wishes for a longer life, let him keep the ties of kinship (Bukhari 5986, Muslim 2557).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 50),
  ('family-time', 'character', 'Spent time with family', 'Give your family unhurried time today — sit, talk, play, or share something together, with your phone away.', 'The best of you is the best to his family, and I am the best of you to my family (Tirmidhi 3895, ḥasan ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 51),
  ('read-beneficial', 'character', 'Read something beneficial', 'Read a few pages of beneficial knowledge today — something that helps your dīn or your life.', 'Whoever follows a path in search of knowledge, Allāh makes easy for him thereby a path to Paradise (Muslim 2699).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 52),
  ('miswak', 'character', 'Cleaned my teeth (miswāk)', 'Clean your teeth with the miswāk (or a brush) at least once today — ideally before a prayer or on waking.', 'Were it not a hardship, I would have ordered the siwāk at every prayer (Bukhari 887, Muslim 252).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 53),
  ('sleep-on-wudu', 'character', 'Slept upon wuḍūʾ', 'Make wuḍūʾ before getting into bed, then lie down on your right side.', 'When you go to bed, perform wuḍūʾ as for prayer, then lie on your right side (Bukhari 247).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 54),
  ('sleeping-adhkar', 'character', 'Said the sleeping adhkār', 'As you lie down, say the sleeping duʿāʾ — at minimum: "Bismika Allāhumma amūtu wa aḥyā."', 'When the Prophet ﷺ went to bed he would say: "Bismika Allāhumma amūtu wa aḥyā" (Bukhari 6324).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 55),
  ('name-allah-over-food', 'character', 'Named & praised Allāh over food', 'Begin each meal with Bismillāh and end it with Alḥamdulillāh.', 'Mention Allāh’s name when you eat (Abu Dawud 3767, Tirmidhi 1858, ḥasan ṣaḥīḥ); Allāh is pleased with the servant who praises Him for his food (Muslim 2734).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 56),
  ('spread-salam', 'character', 'Spread the salām', 'Greet fellow Muslims with as-salāmu ʿalaykum — those you know and those you don’t.', 'Spread salām among you and you will love one another and enter Paradise (Muslim 54).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 57),
  ('dua-for-a-brother', 'character', 'Made duʿāʾ for someone in their absence', 'Make a sincere duʿāʾ, by name, for a fellow Muslim who isn’t present.', 'The duʿāʾ of a Muslim for his absent brother is answered; an angel says: and for you the same (Muslim 2733).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 58),
  ('eat-together', 'character', 'Shared a meal with others', 'Eat at least one meal today with family or others — from a shared plate where you can — rather than alone.', 'Eat together and not separately, for the blessing is in the company (Abu Dawud 3764, Ibn Mājah 3286, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 59),
  ('focused-study', 'growth', 'Studied with focus', 'Spend at least 30 focused minutes on your studies — schoolwork, a course, or a skill — phone away and notifications off. Open with the duʿāʾ for beneficial knowledge: Allāhumma nfaʿnī bimā ʿallamtanī wa ʿallimnī mā yanfaʿunī.', 'Seeking knowledge is an obligation upon every Muslim (Ibn Mājah 224, ḥasan); switching between tasks and notifications measurably erodes learning and recall compared to one uninterrupted block (Uncapher & Wagner, PNAS 2016).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 60),
  ('family-study-circle', 'growth', 'Studied together as a family', 'Set aside time to study something together as a family — Qurʾān, a ḥadīth, homework, or a new skill — opening with Bismillāh and a duʿāʾ for beneficial knowledge.', 'Whenever people gather in a house of Allāh, reciting His Book and studying it among themselves, tranquility descends upon them, mercy envelops them, and the angels surround them (Muslim 2699).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 61),
  ('arabic-study', 'growth', 'Studied Arabic', 'Spend at least 20 focused minutes learning Arabic — grammar, vocabulary, or reading practice — phone away and notifications off.', 'ʿUmar ibn al-Khaṭṭāb said, "Learn Arabic, for it is part of your religion" (Ibn Abī Shaybah, athar); the Qurʾān was sent down "in Arabic, that you may understand" (12:2).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 62),
  ('arabic-vocabulary', 'growth', 'Learned new Arabic words', 'Learn at least 5 new Arabic words today — from the Qurʾān, a wordlist, or a lesson — and review them once before you sleep.', 'Understanding the Qurʾān and Sunnah in their own language is itself a religious obligation, since what is needed to fulfil an obligation is obligatory (Ibn Taymiyyah, Iqtiḍāʾ aṣ-Ṣirāṭ al-Mustaqīm).', '{0,1,2,3,4,5,6}'::integer[], null, 5, 'words', false, 63),
  ('qaylulah', 'wellbeing', 'Took a short midday rest', 'Rest or nap for 10–20 minutes around midday (qaylūlah) to restore energy for the day and for night prayer.', 'The Companions would take a midday rest (qaylūlah), a Prophetic practice (Bukhari 940).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 64),
  ('moderate-eating', 'wellbeing', 'Stopped eating before I was full', 'At your main meal, stop while still a little hungry — roughly a third for food, a third for drink, a third for breath.', 'The son of Ādam fills no vessel worse than his stomach (Tirmidhi 2380, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 65),
  ('sleep-early', 'wellbeing', 'Slept early after ʿIshāʾ', 'Be in bed within about an hour of ʿIshāʾ, skipping the idle late night, so you can rise easily for Fajr.', 'The Prophet ﷺ disliked sleeping before ʿIshāʾ and idle talk after it (Bukhari 568).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 66),
  ('stay-up-after-fajr', 'wellbeing', 'Stayed up after Fajr', 'After praying Fajr, stay up and begin your day — in dhikr until sunrise where you can — rather than returning to bed.', 'When the Prophet ﷺ prayed Fajr he would remain seated in his place until the sun had fully risen (Muslim 670); “O Allāh, bless my ummah in its early mornings” (Abu Dawud 2606, Tirmidhi 1212, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 67),
  ('daily-walk', 'wellbeing', 'Went for a walk', 'Take a brisk walk of 10–30 minutes — make it your walk to the masjid wherever you can.', 'For every step toward the masjid a rank is raised and a sin erased (Muslim 666).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 68),
  ('exercise-daily', 'wellbeing', 'Moved my body', 'Get 20–30 minutes of deliberate exercise today — a brisk walk, a run, training, or a sport — enough to raise your heart rate.', 'The strong believer is better and more beloved to Allāh than the weak believer, though there is good in both (Muslim 2664).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 69),
  ('hydrate-water', 'wellbeing', 'Drank water', 'Stay hydrated — aim for 6–8 cups across the day, drinking seated and in a few breaths rather than one gulp.', 'The Prophet ﷺ would drink in three breaths and forbade gulping in one (Muslim 2028).', '{0,1,2,3,4,5,6}'::integer[], null, 8, 'cups', false, 70),
  ('gratitude', 'wellbeing', 'Counted a blessing', 'Pause once today to name one specific blessing and give thanks (shukr) to Allāh for it (Alḥamdulillāh).', '"If you are grateful, I will surely increase you" (Qurʾān 14:7); whoever thanks not people thanks not Allāh (Tirmidhi 1954, ṣaḥīḥ).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 71),
  ('black-seed-daily', 'wellbeing', 'Took black seed', 'Take a small daily amount of black seed (ḥabbat al-barakah / Nigella sativa) — about half a teaspoon of the seeds or oil, often taken with honey.', 'In the black seed is a remedy for every disease except death (Bukhari 5688, Muslim 2215).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 72),
  ('dates-morning', 'wellbeing', 'Ate dates in the morning', 'Eat a few dates in the morning — the Sunnah is seven ʿAjwa dates on an empty stomach.', 'Whoever eats seven ʿAjwa dates in the morning, no poison or magic will harm him that day (Bukhari 5445, Muslim 2047).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 73),
  ('honey-daily', 'wellbeing', 'Drank honey water', 'Stir a spoon of honey into a glass of warm water and drink it — ideally in the morning, on an empty stomach.', 'In it is healing for people (Qurʾān 16:69); the Prophet ﷺ recommended honey for a stomach ailment (Bukhari 5684, Muslim 2217).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 74),
  ('olive-oil', 'wellbeing', 'Used olive oil in my food', 'Add olive oil to your food today — drizzle it over a meal or use it in cooking.', 'Eat olive oil and anoint yourselves with it, for it is from a blessed tree (Tirmidhi 1851, Ibn Mājah 3319, ḥasan).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 75),
  ('vinegar-water', 'wellbeing', 'Drank vinegar water', 'Stir a tablespoon of vinegar into a glass of water and drink it — ideally before a meal.', '"Vinegar is an excellent condiment" (Muslim 2052); diluted vinegar before a meal also modestly blunts the after-meal blood-sugar rise (Santos et al., narrative review, Clinical Nutrition ESPEN 2019).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 76),
  ('vitamin-d', 'wellbeing', 'Took vitamin D3', 'Take a vitamin D3 supplement with a meal — about 1000–2000 IU daily (confirm your own level with your doctor).', 'Deficiency is common with limited sun exposure or covered skin; daily D3 reliably restores healthy blood levels, though it adds no extra heart or cancer protection once you’re replete (VITAL trial, Manson et al., NEJM 2019).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 77),
  ('omega-3', 'wellbeing', 'Took omega-3', 'Take an omega-3 (EPA/DHA) supplement with a meal — aim for about 1g combined EPA+DHA, or eat oily fish instead.', 'EPA/DHA omega-3s robustly lower triglycerides (AHA Science Advisory, Circulation 2019); broad heart-disease prevention from supplements is small (Cochrane review, 2020) — most worthwhile if you rarely eat oily fish.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 78),
  ('creatine', 'wellbeing', 'Took creatine', 'Take 3–5g of creatine monohydrate, mixed into water or a drink — any time of day, every day.', 'Among the most-studied supplements: 3–5g a day improves strength, lean mass and exercise performance with a strong safety record (ISSN Position Stand, Kreider et al., 2017). It also modestly aids memory — most in older adults and under stress or sleep loss (meta-analysis, Nutrition Reviews 2023).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 79),
  ('magnesium', 'wellbeing', 'Took magnesium', 'Take about 200–400mg of magnesium (glycinate or citrate) in the evening.', 'Low magnesium intake is widespread; supplements modestly shorten the time to fall asleep, though overall sleep-quality evidence is still limited (systematic review in older adults, 2021).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 80),
  ('protein-morning', 'wellbeing', 'Ate 30g protein after waking', 'Within an hour or two of waking, eat a meal with at least 30g of protein — eggs, yoghurt, a shake, or similar.', 'About 30g of protein per meal maximally stimulates muscle protein synthesis, and a protein-rich first meal curbs morning hunger (Mamerow et al., J. Nutr. 2014).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 81),
  ('multivitamin', 'wellbeing', 'Took a multivitamin', 'Take a daily multivitamin with breakfast as a simple nutritional safety-net.', 'A daily multivitamin fills common dietary gaps; it modestly aided cognition in older adults (COSMOS, Alzheimer’s & Dementia 2023) and lowered total cancer ~8% in older men (Physicians’ Health Study II, JAMA 2012) — real but modest benefits.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 82),
  ('citicoline', 'wellbeing', 'Took citicoline', 'Take 250–500mg of citicoline (CDP-choline) with a meal — the choline form best studied for memory. Eggs are the food-first source.', 'Choline feeds acetylcholine, the memory neurotransmitter, and most people fall short of the recommended intake. 500mg a day improved episodic and overall memory in older adults with age-related memory decline (Nakazaki et al., J. Nutr. 2021) — promising, though industry-funded and clearest in older adults, not the already-sharp.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 83),
  ('vitamin-b12', 'wellbeing', 'Took vitamin B12', 'Take a vitamin B12 supplement if you eat little or no meat, are older, or take metformin — the groups most likely to run low (confirm your level with your doctor).', 'A B12 shortfall is a real, reversible cause of memory and nerve trouble. Homocysteine-lowering B vitamins slowed brain shrinkage and cognitive decline in older adults with mild impairment (VITACOG, Smith et al., PLoS One 2010) — the benefit concentrated in those who were low to begin with, not everyone.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 84),
  ('morning-daylight', 'wellbeing', 'Got morning daylight', 'Get 5–15 minutes of outdoor daylight within an hour of waking — step outside, even on a cloudy day.', 'Morning light is the strongest signal that sets your body clock, improving daytime alertness, mood and night-time sleep (Blume et al., Somnologie 2019).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 85),
  ('vegetables', 'wellbeing', 'Ate vegetables', 'Eat at least two servings of vegetables today — add them to meals or have them as snacks.', 'Higher vegetable intake tracks with much lower risk of heart disease and early death — up to ~31% lower all-cause mortality near 800g a day of fruit and veg (Aune et al., Int. J. Epidemiol. 2017).', '{0,1,2,3,4,5,6}'::integer[], null, 2, 'servings', false, 86),
  ('walk-after-meal', 'wellbeing', 'Walked after a meal', 'Take a 10-minute walk soon after one of your main meals.', 'A short walk soon after eating meaningfully blunts the post-meal blood-sugar spike (meta-analysis, Sports Medicine 2022).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 87),
  ('eating-window', 'wellbeing', 'Kept a 10-hour eating window', 'Take today’s first and last bite within one 10-hour stretch — say 9am–7pm — and keep everything outside it to water or unsweetened drinks.', 'A consistent 10-hour eating window improved weight, blood pressure and cholesterol in adults with metabolic syndrome (Wilkinson et al., Cell Metabolism 2020); without calorie rules, 16:8 alone added little weight loss (TREAT trial, JAMA Internal Medicine 2020) — the window is scaffolding, not magic.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 88),
  ('finish-eating-early', 'wellbeing', 'Finished eating 3 hours before bed', 'Take your last bite at least 3 hours before you get into bed — after that, water only.', 'The same meals eaten late increased hunger and lowered calorie burn in a controlled crossover (Vujović et al., Cell Metabolism 2022); eating earlier in the day improved insulin sensitivity and blood pressure even without weight loss (Sutton et al., Cell Metabolism 2018).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 89),
  ('phone-curfew-9pm', 'wellbeing', 'Kept screens off after 9pm', 'Put your phone, TV, and other screens away for the night by 9pm — use the evening for worship, family, or rest instead. Adjust the cutoff hour to fit your own routine.', 'The Prophet ﷺ disliked idle talk after ʿIshāʾ (Bukhari 568); mobile use close to bedtime tracks with later sleep and more next-day tiredness (Exelmans & Van den Bulck, Soc. Sci. Med. 2016).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 90),
  ('screens-away', 'wellbeing', 'Put screens away before sleep', 'Put your phone and other screens away at least 30 minutes before you sleep, and leave the phone charging out of arm’s reach of your bed.', 'Reading a bright screen before bed delays melatonin, pushes sleep later and dulls next-morning alertness (Chang et al., PNAS 2015) — and the Prophet ﷺ disliked idle talk after ʿIshāʾ (Bukhari 568).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 91),
  ('sleep-7-hours', 'wellbeing', 'Gave sleep at least 7 hours', 'Be in bed, lights out, at least 7 hours before your wake-up time — count back from when you rise and hold that line.', 'Adults need 7 or more hours a night for healthy attention, mood, metabolism and immunity — the joint consensus of the American Academy of Sleep Medicine and the Sleep Research Society (Watson et al., Sleep 2015).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 92),
  ('wake-set-time', 'wellbeing', 'Woke at my set time', 'Pick a single wake-up time and be out of bed within 30 minutes of it — weekends included.', 'In over 60,000 UK adults, a regular sleep–wake rhythm predicted lower mortality risk more strongly than sleep duration itself (Windred et al., Sleep 2024); irregular timing also tracks with worse metabolic health (MESA cohort, Diabetes Care 2019).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 93),
  ('caffeine-cutoff', 'wellbeing', 'Cut caffeine after early afternoon', 'Have your last coffee, tea, or other caffeine by early afternoon — say 2pm — so it clears your system well before bed.', 'Caffeine taken even 6 hours before bed measurably cut total sleep time (Drake et al., Journal of Clinical Sleep Medicine 2013).', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 94),
  ('max-one-snooze', 'wellbeing', 'Snoozed at most once', 'Let your alarm go off, snooze at most once, then get up — no repeated dozing.', 'A short snooze period didn’t measurably hurt alertness or mood on waking (Persson & Sahlin, Stockholm University, 2022) — but repeated snoozing fragments the last sleep cycle and deepens grogginess, so cap it at one.', '{0,1,2,3,4,5,6}'::integer[], null, null, null, false, 95)
insert into public.hijri_months (month, name) values
  (1, 'Muḥarram'),
  (2, 'Ṣafar'),
  (3, 'Rabīʿ al-Awwal'),
  (4, 'Rabīʿ al-Thānī'),
  (5, 'Jumādā al-Awwal'),
  (6, 'Jumādā al-Thānī'),
  (7, 'Rajab'),
  (8, 'Shaʿbān'),
  (9, 'Ramaḍān'),
  (10, 'Shawwāl'),
  (11, 'Dhū al-Qaʿdah'),
  (12, 'Dhū al-Ḥijjah')
